#!/usr/bin/env python3
"""explain_branches.py -- the evaluation branch file of the explanation script revision 4, generated by rule
(plan/c1_closure_explain_rev4_spec_20261118.md 10.2; judgement rules 8.13 item 5).

    python3 -I explain_branches.py --out branches.txt [--candidates FILE] [--admitted FILE]...

Data branches: D1, and for each admission file the data branch its `branch` line names (D2 or D2[kinds]); readings for
each data branch: R0, each of Ra-Rf alone, all six.  Without a candidate list no D2 branch is written.  No row id, key or
expected verdict is read or written.  rc 0 written, 2 an admission file without a candidate list or not of its form, 64 usage.
"""
import argparse
import hashlib
import os
import re
import sys

READINGS = ["Ra", "Rb", "Rc", "Rd", "Re", "Rf"]


def sha(path):
    with open(path, "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()


def bid(data, readings):
    d = re.sub(r"[^A-Za-z0-9_.-]", "_", data.replace("[", "_").replace("]", "").replace(",", "_"))
    r = "R0" if readings == ["R0"] else ("all" if readings == READINGS else "_".join(readings))
    return "%s-%s" % (d, r)


def main(argv):
    ap = argparse.ArgumentParser()
    ap.add_argument("--out")
    ap.add_argument("--candidates")
    ap.add_argument("--admitted", action="append", default=[])
    o = ap.parse_args(argv)
    if not o.out or os.path.exists(o.out):
        print("explain_branches.py: --out NEW_FILE is required", file=sys.stderr)
        return 64
    if o.admitted and not o.candidates:
        print("explain_branches.py: admission files need the candidate list", file=sys.stderr)
        return 2
    data = [("D1", "none", "none")]
    for p in o.admitted:
        with open(p, encoding="utf-8") as f:
            m = re.search(r"^branch (.+)$", f.read(), re.M)
        if not m or not re.fullmatch(r"D2(\[[^\]]+\])?", m.group(1)):
            print("explain_branches.py: %s has no D2 branch line" % p, file=sys.stderr)
            return 2
        data.append((m.group(1), os.path.abspath(p), sha(p)))
    lines = []
    for d, path, h in data:
        for rd in [["R0"]] + [[r] for r in READINGS] + [READINGS]:
            lines.append("branch %s data=%s readings=%s admitted=%s admitted_sha256=%s" % (bid(d, rd), d, ",".join(rd), path, h))
    with open(o.out, "w") as f:
        f.write("kz-eval-branches 1\n")
        f.write("rule judgement rules 8.13 item 5 (2026-11-18): data branches D1 and D2 (and D2[<kinds>] for each admission "
                "file given) x readings R0, each of Ra-Rf alone, all six\n")
        f.write("candidates %s\n" % (sha(o.candidates) if o.candidates else "none"))
        for ln in lines:
            f.write(ln + "\n")
        f.write("lines %d\nend\n" % len(lines))
    print("branches %d (data branches %d)" % (len(lines), len(data)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
